#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;
vector<long long> baseW, baseW_;

long long modPower(long long base, int exp) {
    long long result = 1;
    long long b = base;
    int e = exp;
    while (e > 0) {
        if (e & 1)
            result = result * b % MOD;
        b = b * b % MOD;
        e >>= 1;
    }
    return result;
}

void initialize() {
    baseW.resize(21);
    baseW_.resize(21);
    for (int h = 0; h <= 20; h++) {
        baseW[h] = modPower(3, (MOD - 1) >> h);
        baseW_[h] = modPower(3, (MOD - 1) - ((MOD - 1) >> h));
    }
}

void fft(vector<int>& array, int size, bool invert) {
    for (int i = 1, j = 0; i < size; i++) {
        int mask = size;
        do {
            j ^= mask >>= 1;
        } while ((j & mask) == 0);
        if (i < j) {
            swap(array[i], array[j]);
        }
    }
    for (int h = 0, blockSize; (blockSize = 1 << h) < size; h++) {
        long long wFactor = invert ? baseW_[h + 1] : baseW_[h + 1];
        for (int start = 0; start < size; start += (blockSize << 1)) {
            long long w = 1;
            for (int j = 0; j < blockSize; j++) {
                int leftIdx = start + j;
                int rightIdx = leftIdx + blockSize;
                long long u = array[leftIdx];
                long long v = (long long)array[rightIdx] * w % MOD;
                array[leftIdx] = (int)((u + v) % MOD);
                array[rightIdx] = (int)((u - v + MOD) % MOD);
                w = w * wFactor % MOD;
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    initialize();

    int n, k;
    cin >> n >> k;
    int nHalf = n / 2;

    int sizePower = 1;
    while (sizePower < nHalf * 9 + 1)
        sizePower <<= 1;

    vector<int> array(sizePower, 0);
    for (int i = 0; i < k; i++) {
        int d;
        cin >> d;
        array[d] = 1;
    }

    fft(array, sizePower, false);
    for (int i = 0; i < sizePower; i++) {
        array[i] = (int)modPower(array[i], nHalf);
    }
    fft(array, sizePower, true);

    long long invSize = modPower(sizePower, MOD - 2);
    for (int i = 0; i < sizePower; i++) {
        array[i] = (int)(array[i] * invSize % MOD);
        if (array[i] < 0)
            array[i] += MOD;
    }

    long long total = 0;
    for (int i = 0; i <= nHalf * 9; i++) {
        long long val = array[i];
        total = (total + val * val) % MOD;
    }

    cout << total << "\n";

    return 0;
}
